import numpy as np, json
from PIL import Image
from scipy import ndimage

TASKS = {t['id']: t for t in json.load(open('tasks.json'))}

def px_of(val, t, axis):
    ticks = t[ax+'_ticks'] if False else t[axis+'_ticks']
    (pa,va),(pb,vb) = (ticks[0]['pixel_x'],ticks[0]['value']),(ticks[1]['pixel_x'],ticks[1]['value']) if axis=='x' else (ticks[0]['pixel_y'],ticks[0]['value']),(ticks[1]['pixel_y'],ticks[1]['value'])
    if t[axis+'_scale']=='linear':
        return pa + (val-va)*(pb-pa)/(vb-va)
    else:
        return pa + (np.log10(val)-np.log10(va))*(pb-pa)/(np.log10(vb)-np.log10(va))

def val_of(px, t, axis):
    ticks = t[axis+'_ticks']
    if axis=='x':
        (pa,va),(pb,vb) = (ticks[0]['pixel_x'],ticks[0]['value']),(ticks[1]['pixel_x'],ticks[1]['value'])
    else:
        (pa,va),(pb,vb) = (ticks[0]['pixel_y'],ticks[0]['value']),(ticks[1]['pixel_y'],ticks[1]['value'])
    if t[axis+'_scale']=='linear':
        return va + (px-pa)*(vb-va)/(pb-pa)
    else:
        return 10**(np.log10(va)+(px-pa)*(np.log10(vb)-np.log10(va))/(pb-pa))

def frame_box(img):
    gray = np.asarray(img).mean(axis=2) < 128
    H,W = gray.shape
    rows = np.where(gray.sum(axis=1) > 0.5*W)[0]
    cols = np.where(gray.sum(axis=0) > 0.5*H)[0]
    return rows.min(), rows.max(), cols.min(), cols.max()

def mask_for(imgi, kind):
    r,g,b = imgi[:,:,0],imgi[:,:,1],imgi[:,:,2]
    mx = np.maximum(np.maximum(r,g),b); mn = np.minimum(np.minimum(r,g),b)
    if kind=='red':  return (r>110)&(r-g>45)&(r-b>45)
    if kind=='blue': return (b>110)&(b-r>45)&(b-g>45)
    if kind=='dark': return (mx<110)&((mx-mn)<45)
    if kind=='green':return (g>90)&(g-r>40)&(g-b>40)
    if kind=='olive':return (r>120)&(g>90)&(b<110)&(r-b>50)&(g-b>30)&(abs(r.astype(int)-g.astype(int))<80)
    if kind=='orange':return (r>150)&(g>60)&(g<180)&(b<110)&(r-b>80)
    raise ValueError

def find_marker_y(imgi, kind, cx, y0,y1, legend=None, half=4):
    m = mask_for(imgi, kind)
    cxi = int(round(cx))
    xs0, xs1 = cxi-half, cxi+half
    sub = m[y0:y1+1, xs0:xs1+1]
    rowc = sub.sum(axis=1)
    # rows belonging to marker have width >= 4 (line ~2-3)
    good = rowc >= 4
    # find largest contiguous run
    best = None
    idx = np.where(good)[0]
    if len(idx)==0: return None
    runs=[]
    start=idx[0]; prev=idx[0]
    for i in idx[1:]:
        if i>prev+1:
            runs.append((start,prev)); start=i
        prev=i
    runs.append((start,prev))
    def score(run):
        a,b = run
        a+=y0; b+=y0
        if legend and a<=legend[1] and b>=legend[0] and xs0<=legend[3] and xs1>=legend[2]:
            return -1
        return int(rowc[run[0]-y0:run[1]-y0+1].sum())
    runs.sort(key=lambda r:-score(r))
    for run in runs:
        a,b = run[0]+y0, run[1]+y0
        if b-a < 2: continue
        if legend and a<=legend[1]+2 and b>=legend[0]-2 and xs0<=legend[3] and xs1>=legend[2]:
            continue
        return (a+b)/2.0
    return None

def extract(fid, Ts, kinds, legend=None, half=4, min_half_run=2):
