    y0,y1,x0,x1 = frame_box(imgi)
    pts = {}
    for kind in kinds:
        out=[]
        for T in Ts:
            cx = px_of(T, t, 'x')
            cy = find_marker_y(imgi, kind, cx, y0+6, y1-6, legend)
            if cy is None:
                out.append((T,None)); continue
            out.append((T, val_of(cy, t, 'y')))
        pts[kind]=out
    return pts, (y0,y1,x0,x1)

def show(fid, kinds, legend=None, Ts=range(320,481,20)):
    pts, fb = extract(fid, list(Ts), kinds, legend)
    print('==',fid,'frame',fb)
