import numpy as np, json
from PIL import Image

TASKS = {t['id']: t for t in json.load(open('tasks.json'))}

def px_of(val, t, axis):
    ticks = t[axis+'_ticks']
    if axis=='x':
        (pa,va),(pb,vb) = (ticks[0]['pixel_x'],ticks[0]['value']),(ticks[1]['pixel_x'],ticks[1]['value'])
    else:
        (pa,va),(pb,vb) = (ticks[0]['pixel_y'],ticks[0]['value']),(ticks[1]['pixel_y'],ticks[1]['value'])
    if t[axis+'_scale']=='linear':
        return pa + (val-va)*(pb-pa)/(vb-va)
    return pa + (np.log10(val)-np.log10(va))*(pb-pa)/(np.log10(vb)-np.log10(va))

def val_of(px, t, axis):
    ticks = t[axis+'_ticks']
    if axis=='x':
        (pa,va),(pb,vb) = (ticks[0]['pixel_x'],ticks[0]['value']),(ticks[1]['pixel_x'],ticks[1]['value'])
    else:
        (pa,va),(pb,vb) = (ticks[0]['pixel_y'],ticks[0]['value']),(ticks[1]['pixel_y'],ticks[1]['value'])
    if t[axis+'_scale']=='linear':
        return va + (px-pa)*(vb-va)/(pb-pa)
    return 10**(np.log10(va)+(px-pa)*(np.log10(vb)-np.log10(va))/(pb-pa))

def frame_box(imgi):
    gray = imgi.mean(axis=2) < 128
    H,W = gray.shape
    rows = np.where(gray.sum(axis=1) > 0.5*W)[0]
    cols = np.where(gray.sum(axis=0) > 0.5*H)[0]
    return int(rows.min()), int(rows.max()), int(cols.min()), int(cols.max())

def mask_for(imgi, kind):
    r,g,b = imgi[:,:,0],imgi[:,:,1],imgi[:,:,2]
    mx = np.maximum(np.maximum(r,g),b); mn = np.minimum(np.minimum(r,g),b)
    if kind=='red':  return (r>110)&(r-g>45)&(r-b>45)
    if kind=='blue': return (b>110)&(b-r>45)&(b-g>45)
    if kind=='dark': return (mx<110)&((mx-mn)<45)
    if kind=='green':return (g>90)&(g-r>40)&(g-b>40)
    if kind=='olive':return (r>120)&(g>90)&(b<110)&(r-b>50)&(g-b>30)
    if kind=='orange':return (r>150)&(g>60)&(g<180)&(b<110)&(r-b>80)
    raise ValueError(kind)

def find_marker_y(imgi, kind, cx, ytop, ybot, legend=None, half=4):
    m = mask_for(imgi, kind)
    cxi = int(round(cx))
    xs0, xs1 = cxi-half, cxi+half
    sub = m[ytop:ybot+1, xs0:xs1+1]
    rowc = sub.sum(axis=1)
    good = rowc >= 4
    idx = np.where(good)[0]
    if len(idx)==0: return None
    runs=[]; start=idx[0]; prev=idx[0]
    for i in idx[1:]:
        if i>prev+1: runs.append((start,prev)); start=i
        prev=i
    runs.append((start,prev))
    def inleg(a,b):
        if not legend: return False
        ly0,ly1,lx0,lx1 = legend
        return a<=ly1 and b>=ly0 and xs1>=lx0 and xs0<=lx1
    cands = [r for r in runs if not inleg(r[0]+ytop, r[1]+ytop)]
    if not cands: cands = runs
    cands.sort(key=lambda r:-int(rowc[r[0]:r[1]+1].sum()))
    for a,b in cands:
        a+=ytop; b+=ytop
        if b-a < 2: continue
        return (a+b)/2.0
    return None

def extract(fid, Ts, kinds, legend=None, half=4, minrun=2):
    """fid: image path. Returns {kind: [(T, yval or None), ...]}, frame box."""
    imgi = np.asarray(Image.open(fid).convert('RGB')).astype(np.int16)
    t = TASKS[fid.split('/')[-1]]
    y0,y1,x0,x1 = frame_box(imgi)
    pts = {}
    for kind in kinds:
        out=[]
        for T in Ts:
            cx = px_of(T, t, 'x')
            cy = find_marker_y(imgi, kind, cx, y0+6, y1-6, legend, half)
            out.append((T, None if cy is None else val_of(cy, t, 'y')))
        pts[kind]=out
    return pts, (y0,y1,x0,x1)

def show(fid, kinds, legend=None, Ts=range(320,481,20), half=4):
    pts, fb = extract(fid, list(Ts), kinds, legend, half)
    print('==',fid,'frame',fb)
    for k,out in pts.items():
        vals=[None if v is None else round(float(v),4) for T,v in out]
        print(' ',k,vals)

def round6(v):
    if v is None: return None
    return float(f'{v:.6g}')
import numpy as np
from tools import *

def mask_c(img, target, tol=48):
    d = np.abs(img.astype(np.int16) - np.array(target, np.int16)).max(axis=2)
    return d <= tol

def mask_gray(img, lo, hi):
    g = img.mean(axis=2)
    return (g >= lo) & (g <= hi) & (img.max(axis=2).astype(int) - img.min(axis=2).astype(int) <= 30)

def filled_centers(mask, r=3, thr=0.72, min_sep=2):
    k = disk(r).astype(float); k /= k.sum()
    dens = ndimage.correlate(mask.astype(float), k, mode='constant')
    peaks = dens >= thr
    lab, n = ndimage.label(peaks)
    out=[]
    for i in range(1, n+1):
        ys, xs = np.where(lab == i)
        # weight by density
        w = dens[ys, xs]
        cx = (xs*w).sum()/w.sum(); cy = (ys*w).sum()/w.sum()
        out.append((cx, cy, len(xs), dens[ys, xs].max()))
    return out

def ring_centers(mask, r, thr=0.55, min_score=0.45):
    k = annulus(r, 1).astype(float); k /= k.sum()
    score = ndimage.correlate(mask.astype(float), k, mode='constant')
    peaks = score >= thr
    # non-max suppression
    m = 2*r+3
    lab, n = ndimage.label(peaks)
    out=[]
    for i in range(1, n+1):
        ys, xs = np.where(lab == i)
        w = score[ys, xs]
        cx = (xs*w).sum()/w.sum(); cy = (ys*w).sum()/w.sum()
        out.append((cx, cy, len(xs), score[ys, xs].max()))
    # merge centers closer than min_dist
    out.sort(key=lambda t:-t[3])
    kept=[]
    mind = 0.7*r
    for c in out:
        if all((c[0]-k[0])**2+(c[1]-k[1])**2 > mind*1.0 for k in kept):
            kept.append(c)
    return kept, score

def overlay(img, centers, fname, color=(255,0,255)):
    out = img.copy()
    for (cx, cy, *_) in centers:
        x, y = int(round(cx)), int(round(cy))
        for dx,dy in [(-5,0),(5,0),(0,-5),(0,5),(0,0)]:
            if 0<=y+dy<out.shape[0] and 0<=x+dx<out.shape[1]:
                out[y+dy, x+dx] = color
    Image.fromarray(out).save(fname)

def report(fname, pts, tick_x, tick_y, xscale, yscale):
    xs, ys = calibrate(pts, tick_x, tick_y, xscale, yscale)
    return xs, ys

