def mask_for(imgi, kind):
    r,g,b = imgi[:,:,0],imgi[:,:,1],imgi[:,:,2]
    mx = np.maximum(np.maximum(r,g),b); mn = np.minimum(np.minimum(r,g),b)
    if kind=='red':  return (r>110)&(r-g>45)&(r-b>45)
    if kind=='blue': return (b>110)&(b-r>45)&(b-g>45)
    if kind=='dark': return (mx<110)&((mx-mn)<45)
    if kind=='green':return (g>90)&(g-r>40)&(g-b>40)
    if kind=='olive':return (r>120)&(g>90)&(b<110)&(r-b>50)&(g-b>30)
    if kind=='orange':return (r>150)&(g>60)&(g<180)&(b<110)&(r-b>80)
    raise ValueError(kind)

def find_marker_y(imgi, kind, cx, ytop, ybot, legend=None, half=4):
    m = mask_for(imgi, kind)
    cxi = int(round(cx))
    xs0, xs1 = cxi-half, cxi+half
    sub = m[ytop:ybot+1, xs0:xs1+1]
    rowc = sub.sum(axis=1)
    good = rowc >= 4
    idx = np.where(good)[0]
    if len(idx)==0: return None
    runs=[]; start=idx[0]; prev=idx[0]
    for i in idx[1:]:
        if i>prev+1: runs.append((start,prev)); start=i
        prev=i
    runs.append((start,prev))
    def inleg(a,b):
        if not legend: return False
        ly0,ly1,lx0,lx1 = legend
        return a<=ly1 and b>=ly0 and xs1>=lx0 and xs0<=lx1
    cands = [r for r in runs if not inleg(r[0]+ytop, r[1]+ytop)]
    if not cands: cands = runs
    cands.sort(key=lambda r:-int(rowc[r[0]:r[1]+1].sum()))
    for a,b in cands:
        a+=ytop; b+=ytop
        if b-a < 2: continue
        return (a+b)/2.0
    return None

def extract(fid, Ts, kinds, legend=None, half=4, minrun=2):
    """fid: image path. Returns {kind: [(T, yval or None), ...]}, frame box."""
    imgi = np.asarray(Image.open(fid).convert('RGB')).astype(np.int16)
    t = TASKS[fid.split('/')[-1]]
    y0,y1,x0,x1 = frame_box(imgi)
    pts = {}
    for kind in kinds:
        out=[]
        for T in Ts:
            cx = px_of(T, t, 'x')
            cy = find_marker_y(imgi, kind, cx, y0+6, y1-6, legend, half)
            out.append((T, None if cy is None else val_of(cy, t, 'y')))
        pts[kind]=out
    return pts, (y0,y1,x0,x1)

def show(fid, kinds, legend=None, Ts=range(320,481,20), half=4):
    pts, fb = extract(fid, list(Ts), kinds, legend, half)
    print('==',fid,'frame',fb)
    for k,out in pts.items():
        vals=[None if v is None else round(float(v),4) for T,v in out]
        print(' ',k,vals)

def round6(v):
    if v is None: return None
    return float(f'{v:.6g}')

import numpy as np, json
from PIL import Image
from scipy import ndimage

ROOT='/home/mato/.cache/real-chart-bench/codex-local/work/pixcal/qwen3.8-27b/part3'
TASKS={t['id']:t for t in json.load(open(f'{ROOT}/tasks.json'))}

def load(fid): return np.asarray(Image.open(f'{ROOT}/images/{fid}').convert('RGB')).astype(np.int16)

def val(px, t, axis):
    if axis=='x':
        a,b=t['x_ticks']; pa,pb=a['pixel_x'],b['pixel_x']
    else:
        a,b=t['y_ticks']; pa,pb=a['pixel_y'],b['pixel_y']
    if t[axis+'_scale']=='linear':
        return a['value'] + (px-pa)*(b['value']-a['value'])/(pb-pa)
    return 10**(np.log10(a['value'])+(px-pa)*(np.log10(b['value'])-np.log10(a['value']))/(pb-pa))

def calib(fid, pts, sortx=True):
    t=TASKS[fid]
    xs=[val(p[0],t,'x') for p in pts]; ys=[val(p[1],t,'y') for p in pts]
    if sortx:
        s=sorted(zip(xs,ys)); xs=[a for a,b in s]; ys=[b for a,b in s]
    return xs,ys

def color_mask(img, color, tol=36):
    d=np.abs(img-np.array(color,np.int16)).sum(axis=2)
    return d<=tol

def gray_mask(img, lo, hi, sat_max=40):
    g=img.mean(axis=2)
    sat=img.max(axis=2)-img.min(axis=2)
    return (g>=lo)&(g<=hi)&(sat<=sat_max)

def blobs(mask, min_size=3, max_size=5000):
    lab,n=ndimage.label(mask)
    out=[]
    for i in range(1,n+1):
        m=lab==i; sz=int(m.sum())
        if sz<min_size or sz>max_size: continue
        ys,xs=np.where(m)
        out.append((float(xs.mean()),float(ys.mean()),sz))
    return out

def eroded_blobs(mask, core=2, min_core_px=2, max_size=2000):
    """Blobs of mask that survive erosion: thick filled markers vs thin lines."""
    d=ndimage.distance_transform_edt(mask)
    cm=d>=core
    lab,n=ndimage.label(cm)
    out=[]
    for i in range(1,n+1):
        m=lab==i; sz=int(m.sum())
        if sz<min_core_px: continue
        ys,xs=np.where(m)
        # centroid in original mask coords (use the full mask around)
        out.append((float(xs.mean()),float(ys.mean()),sz))
    return out

def holes(mask, min_size=2, max_size=200):
    """White holes fully enclosed by mask -> marker centers for open markers."""
    closed=ndimage.binary_closing(mask, structure=np.ones((2,2)))
    lab,n=ndimage.label(~closed)
    # background = label containing corner
    bg=lab[0,0]
    out=[]
    for i in range(1,n+1):
        if i==bg: continue
        m=lab==i; sz=int(m.sum())
        if sz<min_size or sz>max_size: continue
        ys,xs=np.where(m)
        h=ys.max()-ys.min()+1; w=xs.max()-xs.min()+1
        if h>12 or w>12: continue
        out.append((float(xs.mean()),float(ys.mean()),sz))
    return out

def nms(pts, mindist):
    pts=sorted(pts,key=lambda p:-p[2]) if len(pts[0])>2 else pts
    kept=[]
    for p in pts:
        if all((p[0]-k[0])**2+(p[1]-k[1])**2>mindist**2 for k in kept):
            kept.append(p)
    return kept

def save_pred(fid, series_list):
    p={}
    try: p=json.load(open(f'{ROOT}/predictions.json'))
    except FileNotFoundError: pass
    p[fid]=series_list
    json.dump(p, open(f'{ROOT}/predictions.json','w'), indent=1)

def det(fid, color, tol=40, core=3, min_core_px=2):
    img=load(fid)
    m=color_mask(img,color,tol)
    eb=eroded_blobs(m, core=core, min_core_px=min_core_px)
    return sorted(eb), m

def det(fid, color, tol=40, core=3, min_core_px=2):
