import numpy as np
from PIL import Image

def hsv(a):
    a = a.astype(float)/255.0
    r,g,b = a[...,0],a[...,1],a[...,2]
    mx = np.maximum(np.maximum(r,g),b); mn = np.minimum(np.minimum(r,g),b)
    d = mx-mn
    h = np.zeros_like(mx)
    m = d>0
    rr=(mx==r)&m; gg=(mx==g)&m; bb=(mx==b)&m
    h[rr]=((g[rr]-b[rr])/d[rr])%6
    h[gg]=((b[gg]-r[gg])/d[gg])+2
    h[bb]=((r[bb]-g[bb])/d[bb])+4
    h=h/6.0
    s = np.zeros_like(mx); s[mx>0]=(d/mx)[m]
    v = mx
    return h*360, s, v

def make_mask(a, kind, sat_min=0.25, val_min=0.20):
    H,S,V = hsv(a)
    def hue_in(h0,h1):
        if h0<h1: return (H>=h0)&(H<h1)
        return (H>=h0)|(H<h1)
    if kind==\"red\":    return hue_in(345,15)&(S>0.45)&(V>0.35)
    if kind==\"blue\":   return hue_in(205,255)&(S>0.30)&(V>0.25)
    if kind==\"teal\":   return hue_in(160,195)&(S>0.30)&(V>0.25)
    if kind==\"green\":  return hue_in(75,150)&(S>0.30)&(V>0.25)
    if kind==\"olive\":  return hue_in(45,75)&(S>0.35)&(V>0.30)
    if kind==\"orange\": return hue_in(18,45)&(S>0.40)&(V>0.35)
    if kind==\"purple\": return hue_in(255,300)&(S>0.25)&(V>0.25)
    if kind==\"black\":  return (S<0.18)&(V<0.42)
    if kind==\"gray0\":  return (S<0.18)&(V<0.13)
    if kind==\"gray46\": return (S<0.18)&(V>=0.13)&(V<0.28)
    if kind==\"gray85\": return (S<0.18)&(V>=0.28)&(V<0.42)
    raise ValueError(kind)
