    if kind=='green':return (g>90)&(g-r>40)&(g-b>40)
    if kind=='olive':return (r>120)&(g>90)&(b<110)&(r-b>50)&(g-b>30)
    if kind=='orange':return (r>150)&(g>60)&(g<180)&(b<110)&(r-b>80)
    raise ValueError(kind)

def find_marker_y(imgi, kind, cx, ytop, ybot, legend=None, half=4):
    m = mask_for(imgi, kind)
    cxi = int(round(cx))
    xs0, xs1 = cxi-half, cxi+half
    sub = m[ytop:ybot+1, xs0:xs1+1]
    rowc = sub.sum(axis=1)
    good = rowc >= 4
    idx = np.where(good)[0]
    if len(idx)==0: return None
    runs=[]; start=idx[0]; prev=idx[0]
    for i in idx[1:]:
        if i>prev+1: runs.append((start,prev)); start=i
        prev=i
    runs.append((start,prev))
    def inleg(a,b):
        if not legend: return False
        ly0,ly1,lx0,lx1 = legend
        return a<=ly1 and b>=ly0 and xs1>=lx0 and xs0<=lx1
    cands = [r for r in runs if not inleg(r[0]+ytop, r[1]+ytop)]
    if not cands: cands = runs
    cands.sort(key=lambda r:-int(rowc[r[0]:r[1]+1].sum()))
    for a,b in cands:
        a+=ytop; b+=ytop
        if b-a < 2: continue
        return (a+b)/2.0
    return None

def extract(fid, Ts, kinds, legend=None, half=4, minrun=2):
    """fid: image path. Returns {kind: [(T, yval or None), ...]}, frame box."""
    imgi = np.asarray(Image.open(fid).convert('RGB')).astype(np.int16)
    t = TASKS[fid.split('/')[-1]]
    y0,y1,x0,x1 = frame_box(imgi)
    pts = {}
    for kind in kinds:
        out=[]
        for T in Ts:
            cx = px_of(T, t, 'x')
            cy = find_marker_y(imgi, kind, cx, y0+6, y1-6, legend, half)
            out.append((T, None if cy is None else val_of(cy, t, 'y')))
        pts[kind]=out
    return pts, (y0,y1,x0,x1)

def show(fid, kinds, legend=None, Ts=range(320,481,20), half=4):
    pts, fb = extract(fid, list(Ts), kinds, legend, half)
    print('==',fid,'frame',fb)
    for k,out in pts.items():
        vals=[None if v is None else round(float(v),4) for T,v in out]
        print(' ',k,vals)

